exercitii.solutie:
def cate_injumatatiri(n):
    cate = 0
    while n > 1:
        cate += 1
        n = n // 2
    return cate

def cate_cifre(n):
    if n == 0:
        return 1
    cate = 0
    while n > 0:
        cate += 1
        n = n // 10
    return cate
